using ASimpleMinecraftServer.Models; using System.Collections.ObjectModel; using System.IO; using System.Windows; using System.Windows.Controls;
namespace ASimpleMinecraftServer.UI.Pages;
public partial class LogAnalyzerView:UserControl { private ServerProfile? _profile; private readonly ObservableCollection<LogFinding> _items=new(); public LogAnalyzerView(){InitializeComponent();FindingsGrid.ItemsSource=_items;} public void Bind(ServerProfile? p){_profile=p;AnalyzeButton.IsEnabled=p is not null;SummaryText.Text=p is null?"Select a server first.":$"Scan the latest log for {p.Name}.";} private void Analyze_Click(object sender,RoutedEventArgs e){_items.Clear();if(_profile is null)return;var path=Path.Combine(_profile.Folder,"logs","latest.log");if(!File.Exists(path)){SummaryText.Text="No logs/latest.log file was found.";return;}var lines=File.ReadAllLines(path); foreach(var line in lines.Where(IsImportant).TakeLast(250)){var lower=line.ToLowerInvariant(); if(lower.Contains("outofmemory")||lower.Contains("java heap space"))Add("Critical","Memory",line,"Increase memory or reduce plugins, view distance, and entity load."); else if(lower.Contains("unsupportedclassversion")||lower.Contains("class file version"))Add("Error","Java compatibility",line,"Install the Java major version required by this Minecraft release."); else if(lower.Contains("could not load")||lower.Contains("failed to load plugin")||lower.Contains("invalidplugin"))Add("Error","Plugin loading",line,"Update or remove the named plugin and verify its dependencies."); else if(lower.Contains("unknown dependency")||lower.Contains("dependenc"))Add("Warning","Dependency",line,"Install the missing dependency or choose a compatible plugin build."); else if(lower.Contains("can't keep up")||lower.Contains("behind"))Add("Warning","Performance",line,"Review CPU load, view distance, simulation distance, and heavy plugins."); else Add(lower.Contains("error")||lower.Contains("exception")?"Error":"Warning","Server log",line,"Review the surrounding log lines and the named plugin or subsystem.");} if(_items.Count==0)Add("Healthy","Summary","No recognized critical patterns were found.","No action required.");SummaryText.Text=$"Scanned {lines.Length:N0} lines and found {_items.Count} actionable item(s).";} private static bool IsImportant(string l){var x=l.ToLowerInvariant();return x.Contains("warn")||x.Contains("error")||x.Contains("exception")||x.Contains("outofmemory")||x.Contains("can't keep up");} private void Add(string s,string c,string m,string a)=>_items.Add(new LogFinding{Severity=s,Category=c,Message=m,SuggestedAction=a});}
